import{_ as a,C as t,o,c as r,E as s,a2 as i}from"./chunks/framework.Cm6XCzck.js";const w=JSON.parse(`{"title":"Cancellation Ends Waiting, Not Ownership","description":"","frontmatter":{"title":"Cancellation Ends Waiting, Not Ownership","date":"2026-08-24","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"How should an asynchronous resource owner react when cancellation arrives during teardown so it neither leaks remaining owned resources nor swallows the caller's cancellation signal?","summary":"A merged OpenAI Agents Python fix treats cancellation during owned dependency cleanup as deferred control flow: finish bounded local teardown, clear ownership state, then re-raise. This preserves two contracts locally but does not prove remote cleanup success.","sources":["research/analysis/Q-20260824-03-cancellation-defers-owner-teardown.md"],"item_id":"Q-20260824-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-24-cancellation-ends-waiting-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-08-24-cancellation-ends-waiting.md","filePath":"en/engineering/2026-08-24-cancellation-ends-waiting.md","lastUpdated":1787666502000}`),c={name:"en/engineering/2026-08-24-cancellation-ends-waiting.md"};function l(d,e,h,p,u,g){const n=t("ArticleCover");return o(),r("div",null,[s(n,{image:"/assets/covers/daily-2026-08-24-cancellation-ends-waiting-cover-v2.png",kicker:"Open-source Engineering · Daily Research",title:"Cancellation Ends Waiting, Not Ownership",summary:"A merged OpenAI Agents Python fix treats cancellation during owned dependency cleanup as deferred control flow: finish bounded local teardown, clear ownership state, then re-raise. This preserves two contracts locally but does not prove remote cleanup success.",version:"Q-20260824-03",status:"Daily Runtime V5 · 2026-08-24",languageHref:"/zh/engineering/2026-08-24-cancellation-ends-waiting",languageLabel:"中文"}),e[0]||(e[0]=i('<h1 id="cancellation-ends-waiting-not-ownership" tabindex="-1">Cancellation Ends Waiting, Not Ownership <a class="header-anchor" href="#cancellation-ends-waiting-not-ownership" aria-label="Permalink to &quot;Cancellation Ends Waiting, Not Ownership&quot;">​</a></h1><p>An asynchronous container owns several sandbox dependencies. While closing one, it receives <code>CancelledError</code>. Immediate propagation respects the caller&#39;s wish to stop waiting, but it can abandon every resource later in the teardown order. Swallowing cancellation finishes cleanup but breaks the caller contract.</p><p>An OpenAI Agents Python change merged on 2026-08-24 preserves both obligations locally. The container captures the first cancellation raised during an owned close, continues attempting the remaining closes, clears its internal lifecycle collections and then re-raises cancellation. A regression verifies both owned values receive one close call and a second <code>aclose()</code> reuses the same cancelled close task without increasing either counter.</p><p>The engineering proposition is: <strong>cancellation ends waiting, not ownership.</strong> For a lifecycle owner, cancellation during teardown should become a deferred terminal signal while bounded local obligations finish. That pattern does not prove remote cleanup succeeded or that ordinary close failures are visible.</p><h2 id="ownership-survives-the-caller-s-control-flow-decision" tabindex="-1">Ownership survives the caller&#39;s control-flow decision <a class="header-anchor" href="#ownership-survives-the-caller-s-control-flow-decision" aria-label="Permalink to &quot;Ownership survives the caller&#39;s control-flow decision&quot;">​</a></h2><p>Cancellation and ownership answer different questions. Cancellation says the caller no longer wants to continue the current wait or computation. Ownership says the component accepted responsibility for resources already created on the caller&#39;s behalf.</p><p>In the selected <code>Dependencies</code> implementation, only factory results marked <code>owns_result=True</code> enter the container-managed owned list. The close path first cancels and awaits active factory tasks, then walks owned results in reverse order. That scope gives the owner a finite set of obligations before it releases local state.</p><p>If cancellation instantly exits the loop, later owned resources never receive their close attempt and internal caches may remain populated. Treating cancellation as permission to abandon them would silently rewrite the ownership contract at the most failure-prone moment.</p><p>Not every resource must have the same policy. For an ephemeral object, immediate abandonment may be acceptable. For a credentialed sandbox, leased worker or billable remote resource, cleanup may be mandatory. The owner should define that class-specific boundary before cancellation arrives.</p><h2 id="defer-propagation-without-swallowing-cancellation" tabindex="-1">Defer propagation without swallowing cancellation <a class="header-anchor" href="#defer-propagation-without-swallowing-cancellation" aria-label="Permalink to &quot;Defer propagation without swallowing cancellation&quot;">​</a></h2><p>The selected mechanism records the first <code>CancelledError</code>, continues through the remaining owned results and clears <code>_pending</code>, active tasks, cache and ownership collections. Only then does it re-raise the saved cancellation.</p><p>This ordering preserves caller semantics: cancellation still reaches the caller. It also preserves bounded owner semantics: every admitted resource receives its local close attempt. Deferral is not a general license to keep working indefinitely after cancellation; it is a way to finish a predefined teardown scope before returning control.</p><p>The pattern resembles a small critical section, but the guarantee comes from explicit lifecycle state rather than shielding all work from cancellation. Systems should keep the post-cancellation scope short, deterministic and observable enough to diagnose stalls.</p><h2 id="one-close-task-creates-local-teardown-identity" tabindex="-1">One close task creates local teardown identity <a class="header-anchor" href="#one-close-task-creates-local-teardown-identity" aria-label="Permalink to &quot;One close task creates local teardown identity&quot;">​</a></h2><p>The first <code>aclose()</code> creates one <code>_close_task</code>; later callers reuse and shield that task rather than starting independent teardown passes. Reverse traversal also deduplicates repeated object references using <code>id(value)</code>. Together, those choices provide local idempotence for the demonstrated container lifecycle.</p><p>The scope matters. Two wrapper objects can refer to the same remote resource while having different Python identities. A resource&#39;s <code>close()</code> can partially succeed before raising. Another process can issue its own close. Reusing one local task proves only that this owner does not launch a second local pass for the tested references.</p><p>Critical remote resources may need a logical resource identifier, idempotency key or lease record shared beyond the process. Local object identity is a useful optimization and regression boundary, not evidence of external uniqueness.</p><h2 id="best-effort-still-needs-an-evidence-channel" tabindex="-1">Best effort still needs an evidence channel <a class="header-anchor" href="#best-effort-still-needs-an-evidence-channel" aria-label="Permalink to &quot;Best effort still needs an evidence channel&quot;">​</a></h2><p>Ordinary exceptions from dependency close methods are intentionally suppressed by <code>_close_best_effort()</code>. That lets teardown continue, which may be the right availability choice. It also means the absence of a terminal cleanup error cannot establish that every resource closed successfully.</p><p>For low-impact objects, silent best effort may be sufficient. Security-, cost- or compliance-sensitive resources need structured failure records and reconciliation. Cancellation should remain the caller-visible control signal, while close failures can be aggregated or written to a separate teardown evidence channel without disappearing.</p><p>The final operational question is remote: after local cancellation or a suppressed close error, what receipt, listing or reconciliation proves the external resource is gone? Until that evidence exists, the defensible result is bounded: the demonstrated owner attempts all local closes and preserves cancellation, but remote success and distributed exactly-once cleanup remain unproved.</p><p><strong>Primary evidence:</strong> <a href="https://github.com/openai/openai-agents-python/commit/72b2c670546942bdaaf66cc8d6b3a67d1a2fe5bc" target="_blank" rel="noreferrer">OpenAI Agents Python merged commit 72b2c670</a>. The implementation and regression support the scoped local teardown behavior described here; they are not independent proof of remote cleanup success or exactly-once effects.</p>',22))])}const f=a(c,[["render",l]]);export{w as __pageData,f as default};
